import { MakeLogicType, afterMount, kea, key, path, props, propsChanged } from 'kea'
import { loaders } from 'kea-loaders'

import { performQuery } from '~/queries/query'
import { HogQLQuery, NodeKind } from '~/queries/schema/schema-general'
import { escapeDottedHogQLIdentifier, hogql } from '~/queries/utils'
import { ExternalDataSource } from '~/types'

import { revenueViewName } from './revenueViewName'

export interface StripeProduct {
    id: string
    name: string
}

export interface ExcludedProductsLogicProps {
    source: ExternalDataSource
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface excludedProductsLogicValues {
    products: StripeProduct[] | null
    productsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface excludedProductsLogicActions {
    loadProducts: () => any
    loadProductsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadProductsSuccess: (
        products: StripeProduct[],
        payload?: any
    ) => {
        products: StripeProduct[]
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface excludedProductsLogicMeta {
    key: string
}

export type excludedProductsLogicType = MakeLogicType<
    excludedProductsLogicValues,
    excludedProductsLogicActions,
    ExcludedProductsLogicProps,
    excludedProductsLogicMeta
>

export const excludedProductsLogic = kea<excludedProductsLogicType>([
    path((key) => ['products', 'revenue_analytics', 'settings', 'excludedProductsLogic', key]),
    props({} as ExcludedProductsLogicProps),
    key((props) => props.source.id),

    loaders(({ props }) => ({
        products: [
            null as StripeProduct[] | null,
            {
                loadProducts: async (): Promise<StripeProduct[]> => {
                    const viewName = escapeDottedHogQLIdentifier(revenueViewName(props.source, 'product_revenue_view'))
                    try {
                        const query: HogQLQuery = {
                            kind: NodeKind.HogQLQuery,
                            query: hogql`SELECT id, name FROM ${hogql.raw(viewName)} ORDER BY name ASC LIMIT 1000`,
                        }
                        const response = await performQuery(query)
                        return (response.results ?? []).map(([id, name]: [string, string | null]) => ({
                            id,
                            name: name || id,
                        }))
                    } catch {
                        return []
                    }
                },
            },
        ],
    })),

    afterMount(({ actions, props }) => {
        if (props.source.revenue_analytics_config.enabled) {
            actions.loadProducts()
        }
    }),
    propsChanged(({ actions, props }, oldProps) => {
        if (props.source.revenue_analytics_config.enabled && !oldProps.source.revenue_analytics_config.enabled) {
            actions.loadProducts()
        }
    }),
])
